INSERT INTO `wp_posts` VALUES (363,1,'2026-02-08 21:12:41','2026-02-08 21:12:41','<!-- wp:acf/page-heading {\"name\":\"acf/page-heading\",\"data\":{\"title\":\"\\u003ch1\\u003eMicrolearning Video Solutions\\u003c/h1\\u003e\",\"_title\":\"field_699a0f54e75a3\",\"description\":\"Statistics have proven that while the need for effective eLearning is increasing, the attention span of most humans is on the decline.\\r\\n\\r\\nHow do we combat both concerns?? \\u003cstrong\\u003eMicrolearning Solutions.\\u003c/strong\\u003e\\r\\n\\r\\nMicrolearning solutions are methods that include short educational spurts in video format to both entertain and educate a growing workforce or student population — optimizing downtime and productivity rates for every booming business.\",\"_description\":\"field_699a0f65e75a4\",\"image\":905,\"_image\":\"field_699a0f73e75a5\",\"link_1\":{\"title\":\"Check out our work!\",\"url\":\"/elearning-video-portfolio/\",\"target\":\"\"},\"_link_1\":\"field_699a0f7ee75a6\",\"link_2\":{\"title\":\"Get a Quote!\",\"url\":\"/elearning-video-animation-companies-free-consultation/\",\"target\":\"\"},\"_link_2\":\"field_699a0f96e75a7\",\"right_to_left\":\"0\",\"_right_to_left\":\"field_699a0f9de75a8\",\"design\":\"simple\",\"_design\":\"field_699a0fefe75a9\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"4rem\"} -->\n<div style=\"height:4rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/video-block {\"name\":\"acf/video-block\",\"data\":{\"right_to_left\":\"0\",\"_right_to_left\":\"field_69ac28bd57647\",\"design\":\"mesh\",\"_design\":\"field_69ac290257648\",\"title\":\"What is a Microlearning Video?\",\"_title\":\"field_6976d60a207b6\",\"content\":\"Microlearning solutions use video to combine hyper-focused content, stunning animation, and exciting audio to produce an eLearning method that works for every student. Slide decks are a thing of the past and just don?t offer the same benefits and desired outcome ? if they even finish it? at all!\\r\\n\\r\\nWith microlearning solutions, less is definitely more ? more engagement, more output? more RESULTS!\",\"_content\":\"field_6976d622207b7\",\"link\":{\"title\":\"Get in Touch\",\"url\":\"/contact-us/\",\"target\":\"\"},\"_link\":\"field_6976d62a207b8\",\"video\":\"https://vimeo.com/727563749?fl=pl\\u0026fe=sh\",\"_video\":\"field_6976d638207b9\",\"thumbnail\":\"\",\"_thumbnail\":\"field_697abd828e0bf\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/grid-items {\"name\":\"acf/grid-items\",\"data\":{\"title\":\"Our Work\",\"_title\":\"field_6977a3f378dce\",\"description\":\"Animation, live action, graphic storytelling, and captivating narratives combine to revolutionize the eLearning corporate training industry ? it?s just what we do. Check out some of our proud customers!\",\"_description\":\"field_6977a40278dcf\",\"items_0_tag\":\"\",\"_items_0_tag\":\"field_69a6591724e81\",\"items_0_title\":\"AT\\u0026T\",\"_items_0_title\":\"field_6977a41d78dd1\",\"items_0_image\":907,\"_items_0_image\":\"field_6977a42478dd2\",\"items_0_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/att-2/\",\"target\":\"\"},\"_items_0_link\":\"field_6977a42d78dd3\",\"items_1_tag\":\"\",\"_items_1_tag\":\"field_69a6591724e81\",\"items_1_title\":\"The Wonderful Company\",\"_items_1_title\":\"field_6977a41d78dd1\",\"items_1_image\":908,\"_items_1_image\":\"field_6977a42478dd2\",\"items_1_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/the-wonderful-company-2/\",\"target\":\"\"},\"_items_1_link\":\"field_6977a42d78dd3\",\"items_2_tag\":\"\",\"_items_2_tag\":\"field_69a6591724e81\",\"items_2_title\":\"ARA (American Rental Association)\",\"_items_2_title\":\"field_6977a41d78dd1\",\"items_2_image\":909,\"_items_2_image\":\"field_6977a42478dd2\",\"items_2_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/american-rental-association/\",\"target\":\"\"},\"_items_2_link\":\"field_6977a42d78dd3\",\"items\":3,\"_items\":\"field_6977a40c78dd0\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"container\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center container\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Our <em>Case Studies<br></em></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">San Diego Zoo</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>High Detail Illustrative + Character</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Loved by children and adults across the globe, the famous San Diego Zoo wanted to create live-action videos featuring their amazing staff scientists on the subject of plant propagation. A tough subject to film, the San Diego Zoo reached out to the experts at Ninja Tropic to handle the job. Animating the staff and explanation, the eLearning modules featured the voice of the scientific explainer videos and were praised by all. The zoo even came back to Ninja Tropic for more!<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Engagedly</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Infographic + Live Action</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Performance management is the forte of Engagedly, but when it came to implementing an eLearning solution that actually performed, they came to us. Engagedly needed a learning strategy for potential customers focused on mentorship and combining polished live action clips with beautiful animation was the perfect solution. At the end of the project, Engagedly had a collection of purposeful content for their subscribers to boost their corporate cultures through advisorship.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/engagedly-mentorship-elearning/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Old Castle</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>High detail Illustrative + 3D</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Procedural training is a challenging feat because traditional instructional methods struggle to keep attention. The experts at Oldcastle Infrastructure veered away from the ?normal slide deck? and opted for animated 3D training to visually demonstrate a new process to their line employees that they could access anytime. Oldcastle?s team connected instantly to the video and were able to implement the new complex process successfully.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/oldcastle-3d-safety-training/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":912,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/MS_Our-case-studies-526x1024.webp\" alt=\"\" class=\"wp-image-912\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Related </strong><em><strong>Solutions<br></strong></em></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":785,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Video-Training-Strategy-2.webp\" alt=\"\" class=\"wp-image-785\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Video Training Strategy</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Looking for eLearning solutions on the go? Mobile Learning is the answer! It offers the flexibility to learn anytime, anywhere, allowing your team to learn on their own terms.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/learning-solutions/video-training-strategy/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":915,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Custom-Development-Training.webp\" alt=\"\" class=\"wp-image-915\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Custom<br>Development Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">When learners visualize themselves in relevant scenarios, scenario-based video eLearning enhances understanding and promotes effective implementation. It?s ideal for hands-on learners!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/learning-solutions/custom-elearning-development-services/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":786,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Corporate-Training.webp\" alt=\"\" class=\"wp-image-786\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Corporate Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Got a few minutes between meetings? Struggling to fit in mandatory training? With demanding schedules, Microlearning solutions from Ninja Tropic offer the condensed learning you need!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/corporate-training/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/hubspot-form {\"name\":\"acf/hubspot-form\",\"data\":{\"title\":\"Get a [gradient]FREE Consultation[/gradient] With Ninja Tropic!\",\"_title\":\"field_697ad122e258a\",\"description\":\"Are you aware of the sheer power of engaging eLearning solutions but not sure where to start? Schedule a?\\u003cstrong\\u003efree 30-minute consultation\\u003c/strong\\u003e?with a Ninja Tropic eLearning expert to analyze your organization?s content objectives and map out the interactive blueprint to achieve them.\",\"_description\":\"field_697ad133e258b\",\"form\":\"\\u003cscript charset=\\u0022utf-8\\u0022 type=\\u0022text/javascript\\u0022 src=\\u0022//js.hsforms.net/forms/embed/v2.js\\u0022\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003c/script\\u003e\\r\\n\\u003cscript\\u003e\\r\\n  hbspt.forms.create({\\r\\n    region: \\u0022na1\\u0022,\\r\\n    portalId: \\u00227816367\\u0022,\\r\\n    formId: \\u0022394c2aa7-ab2d-43b4-8cf2-d230dd4662bf\\u0022\\r\\n  });\\r\\n\\u003c/script\\u003e\",\"_form\":\"field_697ad143e258c\"},\"mode\":\"preview\"} /-->','Microlearning Solutions | Video Elearning and Video Animation Company.','','publish','closed','closed','','microlearning-solutions','','','2026-06-28 00:26:28','2026-06-28 00:26:28','',333,'http://localhost:8080/?page_id=363',0,'page','',0),(381,1,'2026-02-08 21:23:27','2026-02-08 21:23:27','<!-- wp:acf/page-heading {\"name\":\"acf/page-heading\",\"data\":{\"title\":\"\\u003ch1\\u003e\\u003cstrong\\u003eLMS Implementation Consultant\\u003c/strong\\u003e\\u003c/h1\\u003e\",\"_title\":\"field_699a0f54e75a3\",\"description\":\"Are you transitioning to a new Learning Management System (LMS) or struggling to maximize the potential of your current one? Ninja Tropic is here to help! We offer comprehensive LMS consulting services to guide you through every step of the process. Get an expert LMS implementation consultant today\",\"_description\":\"field_699a0f65e75a4\",\"image\":957,\"_image\":\"field_699a0f73e75a5\",\"link_1\":{\"title\":\"Check out our work!\",\"url\":\"#\",\"target\":\"\"},\"_link_1\":\"field_699a0f7ee75a6\",\"link_2\":{\"title\":\"Get a Quote!\",\"url\":\"#\",\"target\":\"\"},\"_link_2\":\"field_699a0f96e75a7\",\"right_to_left\":\"0\",\"_right_to_left\":\"field_699a0f9de75a8\",\"design\":\"simple\",\"_design\":\"field_699a0fefe75a9\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"1\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"gradient\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch1\\u003e# 1 LMS \\u003cem\\u003eImplementation Consultant\\u003c/em\\u003e\\u003c/h1\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"\\u003ch2\\u003eWhy Choose Ninja Tropic for LMS Consulting?\\u003c/h2\\u003e\\r\\n\\u0026nbsp;\\r\\n\\u003ch3\\u003eExpert Guidance:\\u003c/h3\\u003e\\r\\nOur experienced consultants have a deep understanding of LMS technology and the challenges organizations face in implementation and optimization.\\r\\n\\u003ch3\\u003eTailored Solutions:\\u003c/h3\\u003e\\r\\nWe know that every organization is unique. We work closely with you to develop customized solutions that align with your specific goals and needs.\\r\\n\\u003ch3\\u003eFocus on Success:\\u003c/h3\\u003e\\r\\nOur mission is to ensure your LMS project is a success. We’ll be with you every step of the way, providing support, training, and troubleshooting.\",\"_description\":\"field_69765f79461c4\",\"image\":\"\",\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Our <em>LMS Consulting</em> Services</strong><br></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"1\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"simple\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch3\\u003eLMS Implementation\\u003c/h3\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"Implementing a new LMS is an investment in your organization’s future. We’ll guide you through the entire implementation process, from vendor selection and system configuration to user training and ongoing support.\\r\\n\\r\\n\\r\\n\",\"_description\":\"field_69765f79461c4\",\"image\":965,\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"0\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"gradient\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch3\\u003eLMS Migration\\r\\n\\u003c/h3\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"Moving to a new training LMS can be complex. We’ll help you plan and execute a smooth migration, ensuring your data is transferred securely and your users are up and running quickly.\\r\\n\\r\\n\",\"_description\":\"field_69765f79461c4\",\"image\":967,\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"1\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"simple\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch3\\u003eLMS Admin Services\\r\\n\\u003c/h3\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"We understand that managing an LMS can be a complex and time-consuming task. Our LMS admin support services can help you with everything from routine maintenance and troubleshooting to advanced reporting and analytics. We’ll work with you to develop a customized support plan that fits your needs and frees up your time to focus on other important tasks.\\r\\n\\r\\n\",\"_description\":\"field_69765f79461c4\",\"image\":968,\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>The <em>LMS implementation</em> process</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"className\":\"is-style-dots\",\"backgroundColor\":\"luminous-vivid-orange\"} -->\n<hr class=\"wp-block-separator has-text-color has-luminous-vivid-orange-color has-alpha-channel-opacity has-luminous-vivid-orange-background-color has-background is-style-dots\"/>\n<!-- /wp:separator -->\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">01</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Content Migration and Development</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Seamlessly integrate our courses into your existing learning management system (LMS) for easy deployment and tracking.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">02</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">User Training and Adoption</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We craft a mobile friendly learning experience that\'s both engaging and effective. We define clear learning objectives, map out the user journey, and select the best content types (videos, quizzes, etc.).</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- wp:spacer {\"height\":\"1.5rem\"} -->\n<div style=\"height:1.5rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">03</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Testing and Quality Assurance</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We create captivating, interactive content, or repurpose your existing materials for mobile delivery. We develop quizzes and tests to reinforce the learning experience and ensure everything is accurate and up-to-date.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">04</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Launch and Rollout</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We package everything for a smooth launch. We optimize content for different devices, load it onto your platform, and thoroughly test it. Your LMS program is ready to go, and we\'ll monitor its performance to ensure success.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- wp:spacer {\"height\":\"1.5rem\"} -->\n<div style=\"height:1.5rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">05</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Monitoring and Optimization</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We track learner performance and platform health continuously, identifying opportunities to improve engagement, content relevance, and overall LMS effectiveness.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">06</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Launch and Promote Your LMS</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We help you communicate the LMS launch to your organization, drive adoption, and keep learners engaged from day one through targeted promotion strategies.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- wp:spacer {\"height\":\"1.5rem\"} -->\n<div style=\"height:1.5rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"lms-step-card\",\"style\":{\"border\":{\"radius\":\"26px\"},\"spacing\":{\"padding\":{\"top\":\"2rem\",\"right\":\"2rem\",\"bottom\":\"2rem\",\"left\":\"2rem\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group lms-step-card\" style=\"border-radius:26px;background-color:#ffffff;border:1px solid rgba(17,17,17,0.06);box-shadow:0 12px 26px rgba(17,17,17,0.12),0 2px 6px rgba(17,17,17,0.06);padding-top:2rem;padding-right:2rem;padding-bottom:2rem;padding-left:2rem\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#e8561e\"}}} -->\n<p style=\"color:#e8561e;font-size:2.5rem;font-weight:700\">07</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Monitor and Evaluate</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We bring your vision to life by analyzing results and making data-driven adjustments. We evaluate learner outcomes and platform metrics to ensure your LMS investment keeps delivering value.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"2.5rem\"} -->\n<div style=\"height:2.5rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"luminous-vivid-orange\",\"textColor\":\"white\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-white-color has-luminous-vivid-orange-background-color has-text-color has-background wp-element-button\" style=\"border-radius:50px\">Get a Quote!</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:spacer {\"height\":\"8rem\"} -->\n<div style=\"height:8rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/cta-box {\"name\":\"acf/cta-box\",\"data\":{\"title\":\"\\u003ch2\\u003e\\u003cem\\u003eLMS Implementation\\u003c/em\\u003e Project Plan Template\\u003c/h2\\u003e\",\"_title\":\"field_69b7663fa36a8\",\"description\":\"Need help planning your LMS project? Download our free project plan template to get started\",\"_description\":\"field_69b76659a36a9\",\"link\":{\"title\":\"Download your Free Template!\",\"url\":\"/elearning-video-animation-companies-free-consultation/\",\"target\":\"\"},\"_link\":\"field_69b76663a36aa\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"8rem\"} -->\n<div style=\"height:8rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Cost of <em>LMS Implementation</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"clas